window.VIBE_HTML = "<!DOCTYPE html>\n<html lang=\"zh-HK\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>AI中文寫作小助理 - 港小專用小學寫作好幫手</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- FontAwesome Icons -->\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n  <!-- Canvas Confetti for rewards -->\n  <script src=\"https://cdn.jsdelivr.net/npm/canvas-confetti@1.6.0/dist/confetti.browser.min.js\"></script>\n  <!-- Google Fonts for friendly rounded typography -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Zen+Maru+Gothic:wght@400;500;700;900&family=Noto+Sans+TC:wght@400;500;700;900&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['\"Zen Maru Gothic\"', '\"Noto Sans TC\"', 'sans-serif'],\n          },\n          colors: {\n            brand: {\n              yellow: '#FFDF00',\n              amber: '#FFB703',\n              orange: '#FB8500',\n              blue: '#0284C7',\n              sky: '#38BDF8',\n              ice: '#E0F2FE',\n              mint: '#10B981',\n              softPink: '#FCE7F3',\n              cardBg: '#FFFDF9'\n            }\n          },\n          boxShadow: {\n            'bubbly': '0 8px 0px 0px rgba(220, 160, 50, 0.4)',\n            'bubbly-active': '0 2px 0px 0px rgba(220, 160, 50, 0.4)',\n            'card-pop': '0 10px 25px -5px rgba(251, 133, 0, 0.1), 0 8px 10px -6px rgba(251, 133, 0, 0.1)',\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    body {\n      background-color: #FEF8ED;\n      background-image: radial-gradient(#FDE68A 1.2px, transparent 1.2px), radial-gradient(#93C5FD 1.2px, #FEF8ED 1.2px);\n      background-size: 48px 48px;\n      background-position: 0 0, 24px 24px;\n    }\n\n    .custom-scroll::-webkit-scrollbar {\n      width: 8px;\n    }\n    .custom-scroll::-webkit-scrollbar-track {\n      background: #FEF3C7;\n      border-radius: 9999px;\n    }\n    .custom-scroll::-webkit-scrollbar-thumb {\n      background: #FBBF24;\n      border-radius: 9999px;\n    }\n\n    @keyframes bounce-gentle {\n      0%, 100% { transform: translateY(0); }\n      50% { transform: translateY(-6px); }\n    }\n    .animate-gentle {\n      animation: bounce-gentle 2.5s infinite ease-in-out;\n    }\n\n    .chat-bubble-ai {\n      position: relative;\n    }\n    .chat-bubble-ai::after {\n      content: '';\n      position: absolute;\n      left: -10px;\n      top: 18px;\n      border-width: 8px 10px 8px 0;\n      border-style: solid;\n      border-color: transparent #FFFFFF transparent transparent;\n    }\n  </style>\n</head>\n\n<body class=\"min-h-screen text-slate-800 flex flex-col antialiased selection:bg-amber-200\">\n\n  <!-- Top Floating Header -->\n  <header class=\"sticky top-0 z-40 bg-white/90 backdrop-blur-md border-b-4 border-amber-300 shadow-sm px-4 py-2.5\">\n    <div class=\"max-w-6xl mx-auto flex items-center justify-between gap-2\">\n      <!-- Logo and Mascot -->\n      <div class=\"flex items-center gap-3 cursor-pointer\" onclick=\"goToStep(0)\">\n        <div class=\"w-12 h-12 bg-amber-400 rounded-2xl flex items-center justify-center text-white text-2xl shadow-md transform -rotate-3 transition hover:rotate-0\">\n          <i class=\"fa-solid fa-pencil-paintbrush\"></i>\n        </div>\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <h1 class=\"text-xl sm:text-2xl font-black text-amber-700 tracking-wide\">AI中文寫作小助理</h1>\n            <span class=\"bg-amber-100 text-amber-800 text-xs font-bold px-2 py-0.5 rounded-full border border-amber-300 hidden sm:inline-block\">香港小學專屬版</span>\n          </div>\n          <p class=\"text-xs text-slate-500 font-medium\">啟發思考，自行寫作，完成文章。</p>\n        </div>\n      </div>\n\n      <!-- Grade & Genre Badges (Visible after setup) -->\n      <div id=\"activeMetaBadges\" class=\"hidden sm:flex items-center gap-2\">\n        <span id=\"badgeGrade\" class=\"px-3 py-1 bg-sky-100 text-sky-800 rounded-full text-xs font-bold border border-sky-300 flex items-center gap-1.5\">\n          <i class=\"fa-solid fa-graduation-cap\"></i> <span id=\"badgeGradeText\">小四</span>\n        </span>\n        <span id=\"badgeGenre\" class=\"px-3 py-1 bg-emerald-100 text-emerald-800 rounded-full text-xs font-bold border border-emerald-300 flex items-center gap-1.5\">\n          <i class=\"fa-solid fa-book-bookmark\"></i> <span id=\"badgeGenreText\">記敘文</span>\n        </span>\n      </div>\n\n      <!-- Action buttons -->\n      <div class=\"flex items-center gap-2\">\n        <button id=\"btnNotebook\" onclick=\"toggleNotebook()\" class=\"px-3 py-2 bg-amber-50 hover:bg-amber-100 text-amber-800 rounded-xl border border-amber-300 text-xs sm:text-sm font-bold flex items-center gap-1.5 transition\">\n          <i class=\"fa-solid fa-box-archive text-amber-600\"></i>\n          <span>百寶錦囊</span>\n          <span id=\"collectedWordsCount\" class=\"w-5 h-5 bg-amber-500 text-white rounded-full text-xs flex items-center justify-center font-bold\">0</span>\n        </button>\n        <button id=\"btnRestart\" onclick=\"confirmReset()\" class=\"p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition\" title=\"重選題目\">\n          <i class=\"fa-solid fa-arrow-rotate-left text-lg\"></i>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- Step Progress Indicator -->\n  <nav class=\"bg-amber-100/70 border-b border-amber-200 py-2.5 px-4 overflow-x-auto\">\n    <div class=\"max-w-4xl mx-auto flex items-center justify-between min-w-[540px]\">\n      <button onclick=\"switchStepTab(1)\" id=\"stepTab-1\" class=\"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-bold transition text-slate-600 hover:bg-amber-200\">\n        <span class=\"w-6 h-6 rounded-full bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-black step-num\">1</span>\n        <span>第一步：審題解析</span>\n      </button>\n      <i class=\"fa-solid fa-chevron-right text-amber-400 text-xs\"></i>\n      <button onclick=\"switchStepTab(2)\" id=\"stepTab-2\" class=\"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-bold transition text-slate-600 hover:bg-amber-200\">\n        <span class=\"w-6 h-6 rounded-full bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-black step-num\">2</span>\n        <span>第二步：靈感引導</span>\n      </button>\n      <i class=\"fa-solid fa-chevron-right text-amber-400 text-xs\"></i>\n      <button onclick=\"switchStepTab(3)\" id=\"stepTab-3\" class=\"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-bold transition text-slate-600 hover:bg-amber-200\">\n        <span class=\"w-6 h-6 rounded-full bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-black step-num\">3</span>\n        <span>第三步：詞彙百寶箱</span>\n      </button>\n      <i class=\"fa-solid fa-chevron-right text-amber-400 text-xs\"></i>\n      <button onclick=\"switchStepTab(4)\" id=\"stepTab-4\" class=\"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-bold transition text-slate-600 hover:bg-amber-200\">\n        <span class=\"w-6 h-6 rounded-full bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-black step-num\">4</span>\n        <span>第四步：作文大綱</span>\n      </button>\n      <i class=\"fa-solid fa-chevron-right text-amber-400 text-xs\"></i>\n      <button onclick=\"switchStepTab(5)\" id=\"stepTab-5\" class=\"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-bold transition text-slate-600 hover:bg-amber-200\">\n        <span class=\"w-6 h-6 rounded-full bg-slate-200 text-slate-700 flex items-center justify-center text-xs font-black step-num\">5</span>\n        <span>第五步：自我檢查</span>\n      </button>\n    </div>\n  </nav>\n\n  <main class=\"flex-1 max-w-5xl w-full mx-auto p-4 sm:p-6 flex flex-col\">\n\n    <!-- VIEW 0: Initial Setup View (Title, Grade, Genre) -->\n    <section id=\"viewSetup\" class=\"my-auto py-4\">\n      <div class=\"bg-white rounded-3xl p-6 sm:p-10 shadow-card-pop border-4 border-amber-300 relative overflow-hidden\">\n        <!-- Background decorative clouds -->\n        <div class=\"absolute -right-8 -bottom-8 opacity-10 text-amber-600 text-9xl pointer-events-none\">\n          <i class=\"fa-solid fa-pen-nib\"></i>\n        </div>\n\n        <div class=\"text-center max-w-2xl mx-auto mb-8\">\n          <div class=\"inline-block p-3 bg-amber-100 rounded-3xl text-amber-600 mb-3 animate-gentle\">\n            <span class=\"text-4xl\">👨‍🏫</span>\n          </div>\n          <h2 class=\"text-2xl sm:text-3xl font-black text-slate-800 mb-2\">你好，我是你的中文寫作小助理「陳老師」</h2>\n          <p class=\"text-slate-600 text-sm sm:text-base leading-relaxed\">\n            今天想寫甚麼題材？無須擔心。陳老師不會直接代寫，而會逐步引導你發揮想像。\n          </p>\n        </div>\n\n        <div class=\"space-y-6 max-w-2xl mx-auto\">\n          <!-- Step 1: Grade Selection -->\n          <div>\n            <label class=\"block text-sm font-black text-slate-700 mb-2 flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-amber-400 text-white flex items-center justify-center text-xs\">1</span>\n              請選擇你的就讀年級：\n            </label>\n            <div class=\"grid grid-cols-3 gap-3\">\n              <label class=\"grade-radio-card cursor-pointer\">\n                <input type=\"radio\" name=\"studentGrade\" value=\"小四\" class=\"peer sr-only\" checked>\n                <div class=\"p-3.5 text-center rounded-2xl border-2 border-slate-200 bg-slate-50 peer-checked:border-sky-500 peer-checked:bg-sky-50 peer-checked:text-sky-800 transition font-bold text-sm sm:text-base hover:bg-slate-100\">\n                  <div class=\"text-xl mb-1\">🌱</div>\n                  小四 (P4)\n                </div>\n              </label>\n              <label class=\"grade-radio-card cursor-pointer\">\n                <input type=\"radio\" name=\"studentGrade\" value=\"小五\" class=\"peer sr-only\">\n                <div class=\"p-3.5 text-center rounded-2xl border-2 border-slate-200 bg-slate-50 peer-checked:border-sky-500 peer-checked:bg-sky-50 peer-checked:text-sky-800 transition font-bold text-sm sm:text-base hover:bg-slate-100\">\n                  <div class=\"text-xl mb-1\">🌿</div>\n                  小五 (P5)\n                </div>\n              </label>\n              <label class=\"grade-radio-card cursor-pointer\">\n                <input type=\"radio\" name=\"studentGrade\" value=\"小六\" class=\"peer sr-only\">\n                <div class=\"p-3.5 text-center rounded-2xl border-2 border-slate-200 bg-slate-50 peer-checked:border-sky-500 peer-checked:bg-sky-50 peer-checked:text-sky-800 transition font-bold text-sm sm:text-base hover:bg-slate-100\">\n                  <div class=\"text-xl mb-1\">🌳</div>\n                  小六 (P6)\n                </div>\n              </label>\n            </div>\n          </div>\n\n          <!-- Step 2: Genre Selection -->\n          <div>\n            <label class=\"block text-sm font-black text-slate-700 mb-2 flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-full bg-amber-400 text-white flex items-center justify-center text-xs\">2</span>\n              請選擇本次作文文體：\n            </label>\n            <div class=\"grid grid-cols-3 gap-3\">\n              <label class=\"genre-radio-card cursor-pointer\">\n                <input type=\"radio\" name=\"writingGenre\" value=\"記敘文\" class=\"peer sr-only\" checked>\n                <div class=\"p-3.5 text-center rounded-2xl border-2 border-slate-200 bg-slate-50 peer-checked:border-emerald-500 peer-checked:bg-emerald-50 peer-checked:text-emerald-800 transition font-bold text-sm sm:text-base hover:bg-slate-100\">\n                  <div class=\"text-xl mb-1\">📖</div>\n                  記敘文\n                  <p class=\"text-[11px] font-normal text-slate-500 mt-1\">敘述事件與經過</p>\n                </div>\n              </label>\n              <label class=\"genre-radio-card cursor-pointer\">\n                <input type=\"radio\" name=\"writingGenre\" value=\"描寫文\" class=\"peer sr-only\">\n                <div class=\"p-3.5 text-center rounded-2xl border-2 border-slate-200 bg-slate-50 peer-checked:border-emerald-500 peer-checked:bg-emerald-50 peer-checked:text-emerald-800 transition font-bold text-sm sm:text-base hover:bg-slate-100\">\n                  <div class=\"text-xl mb-1\">🎨</div>\n                  描寫文\n                  <p class=\"text-[11px] font-normal text-slate-500 mt-1\">寫人・寫景・繪物</p>\n                </div>\n              </label>\n              <label class=\"genre-radio-card cursor-pointer\">\n                <input type=\"radio\" name=\"writingGenre\" value=\"說明文\" class=\"peer sr-only\">\n                <div class=\"p-3.5 text-center rounded-2xl border-2 border-slate-200 bg-slate-50 peer-checked:border-emerald-500 peer-checked:bg-emerald-50 peer-checked:text-emerald-800 transition font-bold text-sm sm:text-base hover:bg-slate-100\">\n                  <div class=\"text-xl mb-1\">💡</div>\n                  說明文\n                  <p class=\"text-[11px] font-normal text-slate-500 mt-1\">解說事物原理方法</p>\n                </div>\n              </label>\n            </div>\n          </div>\n\n          <!-- Step 3: Topic Input -->\n          <div>\n            <label for=\"topicInput\" class=\"block text-sm font-black text-slate-700 mb-2 flex items-center justify-between\">\n              <span class=\"flex items-center gap-2\">\n                <span class=\"w-6 h-6 rounded-full bg-amber-400 text-white flex items-center justify-center text-xs\">3</span>\n                請輸入作文題目：\n              </span>\n              <span class=\"text-xs text-amber-600 font-bold\">小提示：可以是學校功課或自選練習</span>\n            </label>\n            <div class=\"relative\">\n              <input type=\"text\" id=\"topicInput\" placeholder=\"例如：一次難忘的參觀、我最心愛的玩具、如何成為好學生...\" \n                class=\"w-full px-5 py-4 text-base sm:text-lg rounded-2xl border-3 border-amber-300 focus:border-amber-500 focus:outline-none focus:ring-4 focus:ring-amber-200 shadow-inner bg-amber-50/30 transition text-slate-800 font-medium\">\n            </div>\n\n            <!-- Preset Samples for HK Primary Students -->\n            <div class=\"mt-3 flex flex-wrap items-center gap-1.5 text-xs text-slate-500\">\n              <span class=\"font-bold text-slate-600\"><i class=\"fa-solid fa-sparkles text-amber-500\"></i> 熱門題目範例：</span>\n              <button type=\"button\" onclick=\"setPresetTopic('一次難忘的露營活動', '記敘文')\" class=\"px-2.5 py-1 bg-amber-100/70 hover:bg-amber-200 text-amber-900 rounded-lg transition font-medium\">一次難忘的露營活動</button>\n              <button type=\"button\" onclick=\"setPresetTopic('我最敬佩的一位老師', '描寫文')\" class=\"px-2.5 py-1 bg-amber-100/70 hover:bg-amber-200 text-amber-900 rounded-lg transition font-medium\">我最敬佩的一位老師</button>\n              <button type=\"button\" onclick=\"setPresetTopic('記一次圖書館大掃除', '記敘文')\" class=\"px-2.5 py-1 bg-amber-100/70 hover:bg-amber-200 text-amber-900 rounded-lg transition font-medium\">記一次圖書館大掃除</button>\n              <button type=\"button\" onclick=\"setPresetTopic('如何保持校園環境清潔', '說明文')\" class=\"px-2.5 py-1 bg-amber-100/70 hover:bg-amber-200 text-amber-900 rounded-lg transition font-medium\">如何保持校園環境清潔</button>\n            </div>\n          </div>\n\n          <!-- Submit Button -->\n          <div class=\"pt-4 text-center\">\n            <button type=\"button\" onclick=\"startWritingCoach()\" id=\"btnStartCoach\" class=\"w-full sm:w-auto px-10 py-4 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white rounded-2xl font-black text-lg sm:text-xl shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 active:translate-y-0 transition flex items-center justify-center gap-3 mx-auto\">\n              <span>開始寫作</span>\n              <i class=\"fa-solid fa-rocket\"></i>\n            </button>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- VIEW 1: STEP 1 - Topic Analysis -->\n    <section id=\"step1View\" class=\"hidden flex-1 flex flex-col gap-4\">\n      <div class=\"bg-white rounded-3xl p-5 sm:p-7 shadow-sm border-2 border-amber-200\">\n        <div class=\"flex flex-wrap items-center justify-between gap-3 border-b border-amber-100 pb-4 mb-4\">\n          <div>\n            <div class=\"text-xs font-bold text-amber-600 uppercase tracking-wider mb-1 flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-compass\"></i> 第一步：審題解析\n            </div>\n            <h2 class=\"text-xl sm:text-2xl font-black text-slate-800\">\n              題目：「<span id=\"displayTopic1\" class=\"text-amber-600\">--</span>」\n            </h2>\n          </div>\n          <span class=\"px-3 py-1 bg-amber-100 text-amber-800 text-xs font-bold rounded-full\">\n            第一步：先審題，再下筆。\n          </span>\n        </div>\n\n        <div id=\"step1Loading\" class=\"py-12 text-center\">\n          <div class=\"inline-block animate-spin text-amber-500 text-4xl mb-3\">\n            <i class=\"fa-solid fa-spinner\"></i>\n          </div>\n          <p class=\"text-slate-600 font-bold\">陳老師正在為你深入剖析題目中的亮點，請稍候...</p>\n        </div>\n\n        <div id=\"step1Content\" class=\"hidden space-y-5\">\n          <!-- 3 Feature Cards: Keywords, Focus, Genre features -->\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n            <!-- Card 1: Keywords -->\n            <div class=\"bg-amber-50/70 border-2 border-amber-200 rounded-2xl p-4.5\">\n              <div class=\"flex items-center gap-2 text-amber-800 font-black mb-2\">\n                <span class=\"w-8 h-8 rounded-xl bg-amber-400 text-white flex items-center justify-center text-sm shadow-sm\"><i class=\"fa-solid fa-key\"></i></span>\n                <h3 class=\"text-base\">題目關鍵字</h3>\n              </div>\n              <ul id=\"keywordsList\" class=\"space-y-1.5 text-sm text-slate-700 pl-1\">\n                <!-- Dynamically filled -->\n              </ul>\n            </div>\n\n            <!-- Card 2: Writing Focus -->\n            <div class=\"bg-sky-50/70 border-2 border-sky-200 rounded-2xl p-4.5\">\n              <div class=\"flex items-center gap-2 text-sky-800 font-black mb-2\">\n                <span class=\"w-8 h-8 rounded-xl bg-sky-400 text-white flex items-center justify-center text-sm shadow-sm\"><i class=\"fa-solid fa-bullseye\"></i></span>\n                <h3 class=\"text-base\">寫作核心重點</h3>\n              </div>\n              <p id=\"focusSummary\" class=\"text-sm text-slate-700 leading-relaxed\">\n                <!-- Dynamically filled -->\n              </p>\n            </div>\n\n            <!-- Card 3: Genre Characteristics -->\n            <div class=\"bg-emerald-50/70 border-2 border-emerald-200 rounded-2xl p-4.5\">\n              <div class=\"flex items-center gap-2 text-emerald-800 font-black mb-2\">\n                <span class=\"w-8 h-8 rounded-xl bg-emerald-500 text-white flex items-center justify-center text-sm shadow-sm\"><i class=\"fa-solid fa-shapes\"></i></span>\n                <h3 class=\"text-base\">文體特色要點</h3>\n              </div>\n              <ul id=\"genrePointsList\" class=\"space-y-1.5 text-sm text-slate-700 pl-1\">\n                <!-- Dynamically filled -->\n              </ul>\n            </div>\n          </div>\n\n          <!-- Coach's warm encouraging quote -->\n          <div class=\"p-4 bg-gradient-to-r from-amber-50 to-orange-50 rounded-2xl border-l-4 border-amber-500 flex items-start gap-3\">\n            <span class=\"text-2xl mt-0.5\">💬</span>\n            <div>\n              <h4 class=\"font-black text-amber-900 text-sm\">陳老師的審題提示：</h4>\n              <p id=\"coachAdviceStep1\" class=\"text-sm text-slate-700 mt-1 leading-relaxed\"></p>\n            </div>\n          </div>\n\n          <div class=\"pt-2 flex justify-end\">\n            <button onclick=\"goToStep(2)\" class=\"px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-xl font-black text-sm shadow-md hover:shadow-lg transition flex items-center gap-2\">\n              <span>已完成審題，前往第二步：靈感引導</span>\n              <i class=\"fa-solid fa-arrow-right\"></i>\n            </button>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- VIEW 2: STEP 2 - Socratic Guiding Questions Chat (One question at a time) -->\n    <section id=\"step2View\" class=\"hidden flex-1 flex flex-col gap-3\">\n      <div class=\"bg-white rounded-3xl p-4 sm:p-6 shadow-sm border-2 border-amber-200 flex-1 flex flex-col min-h-[500px]\">\n        \n        <!-- Header -->\n        <div class=\"flex items-center justify-between border-b border-amber-100 pb-3 mb-3\">\n          <div class=\"flex items-center gap-2.5\">\n            <div class=\"w-10 h-10 rounded-2xl bg-amber-400 text-white flex items-center justify-center text-lg shadow-sm\">\n              <i class=\"fa-solid fa-lightbulb\"></i>\n            </div>\n            <div>\n              <div class=\"flex items-center gap-2\">\n                <h3 class=\"font-black text-slate-800 text-base sm:text-lg\">第二步：引導構思（一對一啟發提問）</h3>\n                <span class=\"bg-amber-100 text-amber-800 text-xs px-2 py-0.5 rounded-full font-bold\">提問階段</span>\n              </div>\n              <p class=\"text-xs text-slate-500\">陳老師每次只提出一個問題。請以自己的話回答，並寫出細節。</p>\n            </div>\n          </div>\n          <!-- Progress badge -->\n          <div class=\"text-right\">\n            <div class=\"text-xs font-bold text-slate-500\">已收集靈感段落</div>\n            <div class=\"text-sm font-black text-amber-600\" id=\"chatQuestionCounter\">問題 1 / 5</div>\n          </div>\n        </div>\n\n        <!-- Chat messages container -->\n        <div id=\"chatScrollArea\" class=\"flex-1 overflow-y-auto custom-scroll pr-2 space-y-4 mb-3 max-h-[420px]\">\n          <!-- Chat bubbles will be injected here -->\n        </div>\n\n        <!-- Typing indicator (hidden by default) -->\n        <div id=\"chatTypingIndicator\" class=\"hidden flex items-center gap-2 text-xs text-amber-600 font-bold p-2 bg-amber-50 rounded-xl mb-2 w-max\">\n          <span class=\"animate-spin\"><i class=\"fa-solid fa-circle-notch\"></i></span>\n          <span>陳老師正在細心閱讀你的回覆並思考下一個問題...</span>\n        </div>\n\n        <!-- Input Area -->\n        <div class=\"border-t border-slate-150 pt-3\">\n          <!-- Quick assistance buttons for students -->\n          <div class=\"flex flex-wrap gap-1.5 mb-2.5 text-xs\">\n            <button onclick=\"appendQuickChat('我有些想不到，老師可以給我一點提示嗎？')\" class=\"px-2.5 py-1 bg-amber-50 hover:bg-amber-100 text-amber-800 rounded-lg border border-amber-200 transition font-medium\">\n              💡 給我一點靈感提示\n            </button>\n            <button onclick=\"appendQuickChat('當時我的心情是既緊張又興奮！')\" class=\"px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-800 rounded-lg border border-sky-200 transition font-medium\">\n              💖 心情描述句\n            </button>\n            <button onclick=\"appendQuickChat('我印象最深的一幕是……')\" class=\"px-2.5 py-1 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 rounded-lg border border-emerald-200 transition font-medium\">\n              🌟 最深刻的一幕\n            </button>\n          </div>\n\n          <form id=\"chatForm\" onsubmit=\"handleStudentAnswer(event)\" class=\"flex gap-2\">\n            <input type=\"text\" id=\"chatStudentInput\" placeholder=\"在此輸入你的想法（例如：故事發生在星期天下午的屋邨公園……）\" \n              class=\"flex-1 px-4 py-3 rounded-xl border-2 border-amber-200 focus:border-amber-400 focus:outline-none focus:ring-2 focus:ring-amber-200 text-sm font-medium text-slate-800\">\n            <button type=\"submit\" id=\"btnSendAnswer\" class=\"px-5 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-xl font-bold text-sm shadow transition flex items-center gap-1.5 whitespace-nowrap\">\n              <span>發送</span>\n              <i class=\"fa-solid fa-paper-plane text-xs\"></i>\n            </button>\n          </form>\n\n          <!-- Step Finish Bar (Shows when at least 3-4 questions answered) -->\n          <div id=\"step2FinishContainer\" class=\"hidden mt-3 p-3 bg-emerald-50 border border-emerald-300 rounded-2xl flex items-center justify-between\">\n            <div class=\"text-xs text-emerald-800 font-bold flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-circle-check text-emerald-600 text-base\"></i>\n              <span>你已收集足夠的構思內容，可以前往詞彙百寶箱。</span>\n            </div>\n            <button onclick=\"goToStep(3)\" class=\"px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-black text-xs shadow transition flex items-center gap-1\">\n              <span>下一步：查看詞彙</span>\n              <i class=\"fa-solid fa-arrow-right text-xs\"></i>\n            </button>\n          </div>\n        </div>\n\n      </div>\n    </section>\n\n    <!-- VIEW 3: STEP 3 - Vocabulary & Sentence Support -->\n    <section id=\"step3View\" class=\"hidden flex-1 flex flex-col gap-4\">\n      <div class=\"bg-white rounded-3xl p-5 sm:p-7 shadow-sm border-2 border-amber-200\">\n        <div class=\"flex flex-wrap items-center justify-between gap-3 border-b border-amber-100 pb-4 mb-4\">\n          <div>\n            <div class=\"text-xs font-bold text-amber-600 uppercase tracking-wider mb-1 flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-gem\"></i> 第三步：詞彙百寶箱\n            </div>\n            <h2 class=\"text-xl sm:text-2xl font-black text-slate-800\">\n              為「<span id=\"displayTopic3\" class=\"text-amber-600\">--</span>」補充詞彙與句式\n            </h2>\n            <p class=\"text-xs text-slate-500 mt-0.5\">按一下詞彙或句子，即可收藏至「百寶錦囊」，寫作時可供參考。</p>\n          </div>\n          <button onclick=\"generateVocabularySupport(true)\" class=\"px-3 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-800 text-xs font-bold rounded-xl border border-amber-200 transition flex items-center gap-1\">\n            <i class=\"fa-solid fa-arrows-rotate\"></i> 換一批新詞語\n          </button>\n        </div>\n\n        <div id=\"step3Loading\" class=\"py-12 text-center\">\n          <div class=\"inline-block animate-spin text-amber-500 text-4xl mb-3\">\n            <i class=\"fa-solid fa-spinner\"></i>\n          </div>\n          <p class=\"text-slate-600 font-bold\">陳老師正在結合你的構思，挑選最適合香港小學生的詞彙與優美句式...</p>\n        </div>\n\n        <div id=\"step3Content\" class=\"hidden space-y-6\">\n          \n          <!-- Category 1: 5 形容詞 -->\n          <div>\n            <div class=\"flex items-center gap-2 mb-2 text-slate-800 font-black text-sm sm:text-base\">\n              <span class=\"w-6 h-6 rounded-lg bg-orange-400 text-white flex items-center justify-center text-xs\">1</span>\n              <span>5個精選形容詞（讓細節更具體）</span>\n            </div>\n            <div id=\"adjContainer\" class=\"grid grid-cols-2 sm:grid-cols-5 gap-2.5\">\n              <!-- Dynamically populated tags -->\n            </div>\n          </div>\n\n          <!-- Category 2: 5 感受詞 -->\n          <div>\n            <div class=\"flex items-center gap-2 mb-2 text-slate-800 font-black text-sm sm:text-base\">\n              <span class=\"w-6 h-6 rounded-lg bg-rose-400 text-white flex items-center justify-center text-xs\">2</span>\n              <span>5個心情感受詞（寫出真情實感）</span>\n            </div>\n            <div id=\"feelingsContainer\" class=\"grid grid-cols-2 sm:grid-cols-5 gap-2.5\">\n              <!-- Dynamically populated tags -->\n            </div>\n          </div>\n\n          <!-- Category 3: 3 個精選成語 -->\n          <div>\n            <div class=\"flex items-center gap-2 mb-2 text-slate-800 font-black text-sm sm:text-base\">\n              <span class=\"w-6 h-6 rounded-lg bg-purple-500 text-white flex items-center justify-center text-xs\">3</span>\n              <span>3個合適成語（附意思及用法說明）</span>\n            </div>\n            <div id=\"idiomsContainer\" class=\"grid grid-cols-1 sm:grid-cols-3 gap-3\">\n              <!-- Dynamically populated idiom cards -->\n            </div>\n          </div>\n\n          <!-- Category 4: 3 個描寫句式 -->\n          <div>\n            <div class=\"flex items-center gap-2 mb-2 text-slate-800 font-black text-sm sm:text-base\">\n              <span class=\"w-6 h-6 rounded-lg bg-sky-500 text-white flex items-center justify-center text-xs\">4</span>\n              <span>3個描寫句式模範（感官／心理／動作）</span>\n            </div>\n            <div id=\"sentencesContainer\" class=\"space-y-2.5\">\n              <!-- Dynamically populated sentence cards -->\n            </div>\n          </div>\n\n          <!-- Encouragement banner -->\n          <div class=\"p-3 bg-amber-50 rounded-2xl border border-amber-200 text-center text-xs text-amber-800 font-bold\">\n            「你已經想到很好的內容，請再逐步完成作文。」\n          </div>\n\n          <div class=\"pt-2 flex justify-between items-center\">\n            <button onclick=\"goToStep(2)\" class=\"px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs sm:text-sm transition\">\n              <i class=\"fa-solid fa-arrow-left mr-1\"></i> 返回修改構思\n            </button>\n            <button onclick=\"goToStep(4)\" class=\"px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-xl font-black text-sm shadow-md hover:shadow-lg transition flex items-center gap-2\">\n              <span>前往整理作文大綱</span>\n              <i class=\"fa-solid fa-arrow-right\"></i>\n            </button>\n          </div>\n        </div>\n\n      </div>\n    </section>\n\n    <!-- VIEW 4: STEP 4 - Structured Essay Outline -->\n    <section id=\"step4View\" class=\"hidden flex-1 flex flex-col gap-4\">\n      <div class=\"bg-white rounded-3xl p-5 sm:p-7 shadow-sm border-2 border-amber-200\">\n        \n        <div class=\"flex flex-wrap items-center justify-between gap-3 border-b border-amber-100 pb-4 mb-4\">\n          <div>\n            <div class=\"text-xs font-bold text-amber-600 uppercase tracking-wider mb-1 flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-sitemap\"></i> 第四步：整理作文大綱\n            </div>\n            <h2 class=\"text-xl sm:text-2xl font-black text-slate-800\">\n              「<span id=\"displayTopic4\" class=\"text-amber-600\">--</span>」專屬思考框架\n            </h2>\n            <p class=\"text-xs text-slate-500 mt-0.5\">提醒：陳老師只提供思路結構框架，請同學自行補充內容細節。</p>\n          </div>\n          <div class=\"flex gap-2\">\n            <button onclick=\"copyOutline()\" class=\"px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold rounded-xl border border-slate-300 transition flex items-center gap-1\">\n              <i class=\"fa-solid fa-copy\"></i> 複製大綱\n            </button>\n            <button onclick=\"printOutline()\" class=\"px-3 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-800 text-xs font-bold rounded-xl border border-amber-200 transition flex items-center gap-1\">\n              <i class=\"fa-solid fa-print\"></i> 列印 / 儲存\n            </button>\n          </div>\n        </div>\n\n        <div id=\"step4Loading\" class=\"py-12 text-center\">\n          <div class=\"inline-block animate-spin text-amber-500 text-4xl mb-3\">\n            <i class=\"fa-solid fa-spinner\"></i>\n          </div>\n          <p class=\"text-slate-600 font-bold\">陳老師正在整合剛才的回答，為你整理清晰的四段式大綱框架...</p>\n        </div>\n\n        <div id=\"step4Content\" class=\"hidden space-y-4\">\n          \n          <!-- Section 1: 開頭 -->\n          <div class=\"p-4 rounded-2xl border-2 border-sky-200 bg-sky-50/40\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <div class=\"flex items-center gap-2 font-black text-sky-900\">\n                <span class=\"w-7 h-7 rounded-xl bg-sky-500 text-white flex items-center justify-center text-xs\">起</span>\n                <h4>【開頭】時間、地點、人物（交代背景）</h4>\n              </div>\n              <span class=\"text-xs text-sky-700 bg-sky-100 px-2.5 py-0.5 rounded-full font-bold\">第一段</span>\n            </div>\n            <div id=\"outlineIntro\" class=\"text-sm text-slate-700 leading-relaxed bg-white p-3 rounded-xl border border-sky-100\">\n              <!-- Dynamically populated -->\n            </div>\n            <!-- Student note field -->\n            <textarea id=\"noteIntro\" rows=\"2\" placeholder=\"✏️ 我的補充筆記（例如：那天是炎熱的星期日早上，我和爸爸媽媽...）\" class=\"w-full mt-2 p-2.5 text-xs rounded-xl border border-sky-200 focus:border-sky-400 focus:outline-none bg-white/80 text-slate-800\"></textarea>\n          </div>\n\n          <!-- Section 2: 經過 -->\n          <div class=\"p-4 rounded-2xl border-2 border-emerald-200 bg-emerald-50/40\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <div class=\"flex items-center gap-2 font-black text-emerald-900\">\n                <span class=\"w-7 h-7 rounded-xl bg-emerald-500 text-white flex items-center justify-center text-xs\">承</span>\n                <h4>【經過】事情發展（按順序記敘）</h4>\n              </div>\n              <span class=\"text-xs text-emerald-700 bg-emerald-100 px-2.5 py-0.5 rounded-full font-bold\">第二段</span>\n            </div>\n            <div id=\"outlineDevelopment\" class=\"text-sm text-slate-700 leading-relaxed bg-white p-3 rounded-xl border border-emerald-100\">\n              <!-- Dynamically populated -->\n            </div>\n            <textarea id=\"noteDev\" rows=\"2\" placeholder=\"✏️ 我的補充筆記（例如：我們先坐巴士到達目的地，然後開始分工合作...）\" class=\"w-full mt-2 p-2.5 text-xs rounded-xl border border-emerald-200 focus:border-emerald-400 focus:outline-none bg-white/80 text-slate-800\"></textarea>\n          </div>\n\n          <!-- Section 3: 高潮 -->\n          <div class=\"p-4 rounded-2xl border-2 border-amber-300 bg-amber-50/40\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <div class=\"flex items-center gap-2 font-black text-amber-900\">\n                <span class=\"w-7 h-7 rounded-xl bg-amber-500 text-white flex items-center justify-center text-xs\">轉</span>\n                <h4>【高潮】最重要事件／最深刻一幕（詳細描寫）</h4>\n              </div>\n              <span class=\"text-xs text-amber-800 bg-amber-100 px-2.5 py-0.5 rounded-full font-bold\">第三段（重點段）</span>\n            </div>\n            <div id=\"outlineClimax\" class=\"text-sm text-slate-700 leading-relaxed bg-white p-3 rounded-xl border border-amber-200\">\n              <!-- Dynamically populated -->\n            </div>\n            <textarea id=\"noteClimax\" rows=\"2\" placeholder=\"✏️ 我的補充筆記（例如：突然下起傾盆大雨，我們的帳篷差點被吹倒，大家互相扶持...）\" class=\"w-full mt-2 p-2.5 text-xs rounded-xl border border-amber-200 focus:border-amber-400 focus:outline-none bg-white/80 text-slate-800\"></textarea>\n          </div>\n\n          <!-- Section 4: 結尾 -->\n          <div class=\"p-4 rounded-2xl border-2 border-purple-200 bg-purple-50/40\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <div class=\"flex items-center gap-2 font-black text-purple-900\">\n                <span class=\"w-7 h-7 rounded-xl bg-purple-500 text-white flex items-center justify-center text-xs\">合</span>\n                <h4>【結尾】感受及反思（點明主題）</h4>\n              </div>\n              <span class=\"text-xs text-purple-800 bg-purple-100 px-2.5 py-0.5 rounded-full font-bold\">第四段</span>\n            </div>\n            <div id=\"outlineEnding\" class=\"text-sm text-slate-700 leading-relaxed bg-white p-3 rounded-xl border border-purple-100\">\n              <!-- Dynamically populated -->\n            </div>\n            <textarea id=\"noteEnding\" rows=\"2\" placeholder=\"✏️ 我的補充筆記（例如：這次經歷讓我明白到團結的重要，我永遠不會忘記這一天...）\" class=\"w-full mt-2 p-2.5 text-xs rounded-xl border border-purple-200 focus:border-purple-400 focus:outline-none bg-white/80 text-slate-800\"></textarea>\n          </div>\n\n          <div class=\"p-3 bg-amber-50 rounded-2xl border border-amber-200 text-center text-xs text-amber-800 font-bold\">\n            「你已經想到很好的內容，請再逐步完成作文。」\n          </div>\n\n          <div class=\"pt-2 flex justify-between items-center\">\n            <button onclick=\"goToStep(3)\" class=\"px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs sm:text-sm transition\">\n              <i class=\"fa-solid fa-arrow-left mr-1\"></i> 返回詞彙庫\n            </button>\n            <button onclick=\"goToStep(5)\" class=\"px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-xl font-black text-sm shadow-md hover:shadow-lg transition flex items-center gap-2\">\n              <span>完成大綱，前往最後的自我檢查</span>\n              <i class=\"fa-solid fa-arrow-right\"></i>\n            </button>\n          </div>\n        </div>\n\n      </div>\n    </section>\n\n    <!-- VIEW 5: STEP 5 - Self-Check & Optional Draft Reflection -->\n    <section id=\"step5View\" class=\"hidden flex-1 flex flex-col gap-4\">\n      <div class=\"bg-white rounded-3xl p-5 sm:p-7 shadow-sm border-2 border-amber-200\">\n        \n        <div class=\"flex flex-wrap items-center justify-between gap-3 border-b border-amber-100 pb-4 mb-4\">\n          <div>\n            <div class=\"text-xs font-bold text-amber-600 uppercase tracking-wider mb-1 flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-clipboard-check\"></i> 第五步：自我檢查與反思\n            </div>\n            <h2 class=\"text-xl sm:text-2xl font-black text-slate-800\">\n              自我檢查清單\n            </h2>\n            <p class=\"text-xs text-slate-500 mt-0.5\">完成作文後，請養成自我檢查的習慣，檢視是否遺漏以下要點：</p>\n          </div>\n          <div id=\"checkProgressBadge\" class=\"px-3 py-1 bg-amber-100 text-amber-800 text-xs font-bold rounded-full\">\n            檢查進度：<span id=\"checkedCount\">0</span> / 6\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          \n          <!-- Left Column: The 6 Checklist items -->\n          <div class=\"space-y-3\">\n            <h3 class=\"font-black text-slate-800 text-sm sm:text-base flex items-center gap-2\">\n              <span class=\"w-6 h-6 rounded-lg bg-emerald-500 text-white flex items-center justify-center text-xs\"><i class=\"fa-solid fa-check\"></i></span>\n              <span>必檢六大要點：</span>\n            </h3>\n\n            <!-- Checklist Item 1 -->\n            <label class=\"flex items-start gap-3 p-3.5 rounded-2xl border-2 border-slate-200 hover:border-emerald-300 bg-slate-50/50 hover:bg-emerald-50/30 cursor-pointer transition\">\n              <input type=\"checkbox\" onchange=\"updateChecklistProgress()\" class=\"check-item mt-1 w-5 h-5 rounded text-emerald-600 focus:ring-emerald-400\">\n              <div>\n                <div class=\"font-bold text-sm text-slate-800\">1. 是否切合題目（沒有離題）？</div>\n                <p class=\"text-xs text-slate-500 mt-0.5\">文章每一段都扣緊「<span class=\"currentTopicInline font-bold text-slate-700\"></span>」，沒有寫偏或廢話。</p>\n              </div>\n            </label>\n\n            <!-- Checklist Item 2 -->\n            <label class=\"flex items-start gap-3 p-3.5 rounded-2xl border-2 border-slate-200 hover:border-emerald-300 bg-slate-50/50 hover:bg-emerald-50/30 cursor-pointer transition\">\n              <input type=\"checkbox\" onchange=\"updateChecklistProgress()\" class=\"check-item mt-1 w-5 h-5 rounded text-emerald-600 focus:ring-emerald-400\">\n              <div>\n                <div class=\"font-bold text-sm text-slate-800\">2. 是否有足夠細節（五感描寫）？</div>\n                <p class=\"text-xs text-slate-500 mt-0.5\">是否寫出所見的顏色與形狀，以及所聞的聲音，使細節具體。</p>\n              </div>\n            </label>\n\n            <!-- Checklist Item 3 -->\n            <label class=\"flex items-start gap-3 p-3.5 rounded-2xl border-2 border-slate-200 hover:border-emerald-300 bg-slate-50/50 hover:bg-emerald-50/30 cursor-pointer transition\">\n              <input type=\"checkbox\" onchange=\"updateChecklistProgress()\" class=\"check-item mt-1 w-5 h-5 rounded text-emerald-600 focus:ring-emerald-400\">\n              <div>\n                <div class=\"font-bold text-sm text-slate-800\">3. 是否有深刻的感受描寫？</div>\n                <p class=\"text-xs text-slate-500 mt-0.5\">不要只寫「我很開心」，須描寫心跳、表情及內心的想法。</p>\n              </div>\n            </label>\n\n            <!-- Checklist Item 4 -->\n            <label class=\"flex items-start gap-3 p-3.5 rounded-2xl border-2 border-slate-200 hover:border-emerald-300 bg-slate-50/50 hover:bg-emerald-50/30 cursor-pointer transition\">\n              <input type=\"checkbox\" onchange=\"updateChecklistProgress()\" class=\"check-item mt-1 w-5 h-5 rounded text-emerald-600 focus:ring-emerald-400\">\n              <div>\n                <div class=\"font-bold text-sm text-slate-800\">4. 是否有清晰段落（起承轉合）？</div>\n                <p class=\"text-xs text-slate-500 mt-0.5\">分段清楚，每段開頭空兩格，層次分明。</p>\n              </div>\n            </label>\n\n            <!-- Checklist Item 5 -->\n            <label class=\"flex items-start gap-3 p-3.5 rounded-2xl border-2 border-slate-200 hover:border-emerald-300 bg-slate-50/50 hover:bg-emerald-50/30 cursor-pointer transition\">\n              <input type=\"checkbox\" onchange=\"updateChecklistProgress()\" class=\"check-item mt-1 w-5 h-5 rounded text-emerald-600 focus:ring-emerald-400\">\n              <div>\n                <div class=\"font-bold text-sm text-slate-800\">5. 標點符號是否正確規範？</div>\n                <p class=\"text-xs text-slate-500 mt-0.5\">逗號、句號、對話引號「」使用準確，沒有一逗到底。</p>\n              </div>\n            </label>\n\n            <!-- Checklist Item 6 -->\n            <label class=\"flex items-start gap-3 p-3.5 rounded-2xl border-2 border-slate-200 hover:border-emerald-300 bg-slate-50/50 hover:bg-emerald-50/30 cursor-pointer transition\">\n              <input type=\"checkbox\" onchange=\"updateChecklistProgress()\" class=\"check-item mt-1 w-5 h-5 rounded text-emerald-600 focus:ring-emerald-400\">\n              <div>\n                <div class=\"font-bold text-sm text-slate-800\">6. 是否運用了至少 2 個成語或好詞？</div>\n                <p class=\"text-xs text-slate-500 mt-0.5\">是否已把詞彙庫中收藏的詞語用於句子。</p>\n              </div>\n            </label>\n          </div>\n\n          <!-- Right Column: Optional Draft Inspection & Teacher Praise -->\n          <div class=\"flex flex-col gap-4\">\n            <div class=\"bg-amber-50/60 border-2 border-amber-200 rounded-2xl p-4 flex-1 flex flex-col\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <h3 class=\"font-black text-amber-900 text-sm sm:text-base flex items-center gap-2\">\n                  <span class=\"w-6 h-6 rounded-lg bg-amber-400 text-white flex items-center justify-center text-xs\"><i class=\"fa-solid fa-wand-magic-sparkles\"></i></span>\n                  <span>選填：請陳老師幫忙檢查初稿</span>\n                </h3>\n              </div>\n              <p class=\"text-xs text-slate-600 mb-2\">\n                如已在紙上或電腦寫成一段文字，可貼於下方。陳老師會給予鼓勵及具體修改建議，但不會代寫。\n              </p>\n              <textarea id=\"studentDraftInput\" rows=\"6\" placeholder=\"在此貼上你寫好的文章段落或全文……\" class=\"w-full flex-1 p-3 text-xs sm:text-sm rounded-xl border border-amber-200 focus:border-amber-400 focus:outline-none bg-white text-slate-800 mb-3\"></textarea>\n              \n              <button onclick=\"requestDraftFeedback()\" id=\"btnDraftCheck\" class=\"w-full py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-xl font-black text-xs sm:text-sm transition flex items-center justify-center gap-2 shadow\">\n                <i class=\"fa-solid fa-chalkboard-user\"></i>\n                <span>請陳老師給予指導評語</span>\n              </button>\n            </div>\n\n            <!-- Teacher Feedback Result Box -->\n            <div id=\"draftFeedbackResult\" class=\"hidden p-4 bg-white rounded-2xl border-2 border-emerald-300 shadow-sm space-y-2\">\n              <div class=\"flex items-center gap-2 text-emerald-800 font-black text-sm\">\n                <i class=\"fa-solid fa-award text-emerald-600 text-lg\"></i>\n                <span>陳老師的鼓勵評語：</span>\n              </div>\n              <div id=\"draftFeedbackText\" class=\"text-xs sm:text-sm text-slate-700 leading-relaxed space-y-2\">\n                <!-- Injected feedback -->\n              </div>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- Grand Celebration & Completion Card -->\n        <div id=\"completionRewardBox\" class=\"hidden mt-6 p-6 bg-gradient-to-r from-amber-100 via-orange-100 to-yellow-100 rounded-3xl border-2 border-amber-300 text-center space-y-3\">\n          <div class=\"text-4xl animate-bounce\">🏆 🌟 📝</div>\n          <h3 class=\"text-xl font-black text-amber-900\">恭喜你完成所有寫作構思與自我檢查！</h3>\n          <p class=\"text-sm text-amber-800 max-w-xl mx-auto leading-relaxed\">\n            你已具備清晰的思路、豐富的詞彙及完整的大綱。現在可以據此完成寫作。\n          </p>\n          <div class=\"text-sm font-black text-amber-900 bg-white/70 py-2 px-4 rounded-full inline-block border border-amber-200\">\n            「你已經想到很好的內容，請再逐步完成作文。」\n          </div>\n          <div>\n            <button onclick=\"celebrateWithConfetti()\" class=\"px-5 py-2.5 bg-amber-500 hover:bg-amber-600 text-white rounded-xl font-bold text-xs shadow transition\">\n              <i class=\"fa-solid fa-gift mr-1\"></i> 再次播放禮花\n            </button>\n          </div>\n        </div>\n\n        <div class=\"pt-4 flex justify-between items-center border-t border-slate-100 mt-6\">\n          <button onclick=\"goToStep(4)\" class=\"px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs sm:text-sm transition\">\n            <i class=\"fa-solid fa-arrow-left mr-1\"></i> 返回查看大綱\n          </button>\n          <button onclick=\"confirmReset()\" class=\"px-5 py-2.5 bg-sky-500 hover:bg-sky-600 text-white rounded-xl font-black text-xs sm:text-sm shadow transition flex items-center gap-1.5\">\n            <i class=\"fa-solid fa-plus\"></i>\n            <span>寫另一篇新題目</span>\n          </button>\n        </div>\n\n      </div>\n    </section>\n\n  </main>\n\n  <!-- Word Bank (百寶錦囊) Slide-over Drawer -->\n  <div id=\"drawerBackdrop\" onclick=\"toggleNotebook()\" class=\"fixed inset-0 bg-slate-900/40 z-50 backdrop-blur-xs transition-opacity duration-300 hidden opacity-0\"></div>\n  <aside id=\"wordBankDrawer\" class=\"fixed top-0 right-0 h-full w-full max-w-md bg-white z-50 shadow-2xl border-l-4 border-amber-300 transform translate-x-full transition-transform duration-300 ease-out flex flex-col\">\n    <!-- Drawer Header -->\n    <div class=\"p-4 bg-amber-50 border-b border-amber-200 flex items-center justify-between\">\n      <div class=\"flex items-center gap-2\">\n        <div class=\"w-9 h-9 rounded-xl bg-amber-400 text-white flex items-center justify-center text-sm shadow\">\n          <i class=\"fa-solid fa-box-archive\"></i>\n        </div>\n        <div>\n          <h3 class=\"font-black text-slate-800 text-base\">我的寫作百寶錦囊</h3>\n          <p class=\"text-xs text-slate-500\">已收集的靈感詞語與句子</p>\n        </div>\n      </div>\n      <button onclick=\"toggleNotebook()\" class=\"p-2 text-slate-400 hover:text-slate-600 rounded-xl\">\n        <i class=\"fa-solid fa-xmark text-lg\"></i>\n      </button>\n    </div>\n\n    <!-- Drawer Content -->\n    <div class=\"flex-1 overflow-y-auto p-4 custom-scroll space-y-4\">\n      <!-- Section: Added Words -->\n      <div>\n        <div class=\"flex items-center justify-between text-xs font-bold text-slate-600 mb-2\">\n          <span><i class=\"fa-solid fa-bookmark text-amber-500 mr-1\"></i> 收藏的形容詞與感受詞</span>\n          <button onclick=\"clearWordBank()\" class=\"text-rose-500 hover:underline\">清空</button>\n        </div>\n        <div id=\"wordBankTags\" class=\"flex flex-wrap gap-2\">\n          <p class=\"text-xs text-slate-400 py-4 text-center w-full\">尚未收藏詞語。在第三步按一下詞卡，即可加入錦囊。</p>\n        </div>\n      </div>\n\n      <!-- Section: Added Idioms & Sentences -->\n      <div>\n        <div class=\"text-xs font-bold text-slate-600 mb-2\">\n          <i class=\"fa-solid fa-feather text-amber-500 mr-1\"></i> 收藏的成語及優美句式\n        </div>\n        <div id=\"wordBankCards\" class=\"space-y-2\">\n          <p class=\"text-xs text-slate-400 py-2 text-center w-full\">暫無收藏長句。</p>\n        </div>\n      </div>\n    </div>\n\n    <!-- Drawer Footer -->\n    <div class=\"p-4 bg-slate-50 border-t border-slate-200\">\n      <button onclick=\"copyWordBankToClipboard()\" class=\"w-full py-2.5 bg-amber-500 hover:bg-amber-600 text-white font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-2\">\n        <i class=\"fa-solid fa-copy\"></i>\n        <span>複製全部收藏內容</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- Friendly Toast Notification Box (Never using alert) -->\n  <div id=\"toastNotification\" class=\"fixed bottom-6 left-1/2 -translate-x-1/2 z-50 bg-slate-800 text-white px-5 py-3 rounded-2xl shadow-xl flex items-center gap-2.5 text-xs sm:text-sm font-bold opacity-0 transition-opacity duration-300 pointer-events-none\">\n    <span id=\"toastIcon\"><i class=\"fa-solid fa-circle-info text-amber-400\"></i></span>\n    <span id=\"toastMessage\">提示訊息</span>\n  </div>\n\n  <!-- Custom Confirmation Modal (Never using confirm()) -->\n  <div id=\"confirmModal\" class=\"fixed inset-0 bg-slate-900/40 z-50 flex items-center justify-center p-4 hidden backdrop-blur-xs\">\n    <div class=\"bg-white rounded-3xl p-6 max-w-sm w-full border-3 border-amber-300 shadow-2xl text-center space-y-4\">\n      <div class=\"w-12 h-12 rounded-2xl bg-amber-100 text-amber-600 text-2xl flex items-center justify-center mx-auto\">\n        <i class=\"fa-solid fa-question\"></i>\n      </div>\n      <div>\n        <h4 class=\"font-black text-slate-800 text-lg\">確定要重新開始嗎？</h4>\n        <p class=\"text-xs text-slate-500 mt-1\">重新開始後，將可以輸入全新題目，當前的構思對話將會重置。</p>\n      </div>\n      <div class=\"flex gap-2\">\n        <button onclick=\"closeConfirmModal()\" class=\"flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl transition\">\n          繼續目前寫作\n        </button>\n        <button onclick=\"resetAllState()\" class=\"flex-1 py-2.5 bg-rose-500 hover:bg-rose-600 text-white font-bold text-xs rounded-xl transition\">\n          確認重新開始\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    /* Global Application State */\n    const appState = {\n      apiKey: \"\", // Left empty for Canvas runtime injection\n      grade: \"小四\",\n      genre: \"記敘文\",\n      topic: \"\",\n      currentStep: 0,\n      collectedWords: new Set(),\n      collectedSentences: [],\n      // Socratic Chat tracking\n      chatHistory: [], // Full message log for UI\n      geminiHistory: [], // Turns for Gemini API\n      questionCount: 0,\n      maxRecommendedQuestions: 5,\n      step1Data: null,\n      step3Data: null,\n      step4Data: null,\n      checkedItems: 0\n    };\n\n    /* System instruction for the primary school writing coach */\n    const SYSTEM_INSTRUCTION_BASE = `你是一位香港資深小學中文科名師「陳老師」，溫柔、風趣、具啟發性，深受小四至小六學生喜愛。\n你的教學核心原則：\n1. 【嚴禁代寫】：絕對不能直接替學生完成全文、直接寫出整段範文、或代替學生作答。\n2. 【優先提問與引導】：透過問問題的方式啟發小學生回憶、觀察生活、表達真情實感。\n3. 【兒童友善】：使用繁體中文（香港小學規範用字及習慣書面語），用語親切、易懂、充滿鼓勵。\n4. 【規範結尾】：每次給學生的回應，最後一句必須獨立成段，原封不動加上：「你已經想到很好的內容，請再逐步完成作文。」`;\n\n    /* Initialize UI */\n    window.addEventListener('DOMContentLoaded', () => {\n      updateNavTabs();\n    });\n\n    /* Quick Preset Topics */\n    function setPresetTopic(topic, genre) {\n      document.getElementById('topicInput').value = topic;\n      // Select corresponding genre radio\n      const genreRadios = document.getElementsByName('writingGenre');\n      genreRadios.forEach(radio => {\n        if (radio.value === genre) radio.checked = true;\n      });\n      showToast(`已選填推薦題目：「${topic}」`, 'fa-sparkles');\n    }\n\n    /* Toast Notification Helper (replaces alert) */\n    function showToast(message, icon = 'fa-circle-info') {\n      const toast = document.getElementById('toastNotification');\n      const toastMsg = document.getElementById('toastMessage');\n      const toastIcon = document.getElementById('toastIcon');\n      \n      toastMsg.textContent = message;\n      toastIcon.innerHTML = `<i class=\"fa-solid ${icon} text-amber-400\"></i>`;\n      \n      toast.classList.remove('opacity-0', 'pointer-events-none');\n      setTimeout(() => {\n        toast.classList.add('opacity-0', 'pointer-events-none');\n      }, 2800);\n    }\n\n    /* Confirmation Modal Helper (replaces confirm) */\n    function confirmReset() {\n      document.getElementById('confirmModal').classList.remove('hidden');\n    }\n    function closeConfirmModal() {\n      document.getElementById('confirmModal').classList.add('hidden');\n    }\n    function resetAllState() {\n      closeConfirmModal();\n      appState.topic = \"\";\n      appState.chatHistory = [];\n      appState.geminiHistory = [];\n      appState.questionCount = 0;\n      appState.collectedWords.clear();\n      appState.collectedSentences = [];\n      appState.step1Data = null;\n      appState.step3Data = null;\n      appState.step4Data = null;\n      appState.checkedItems = 0;\n      updateWordBankCount();\n      goToStep(0);\n      showToast(\"已重置寫作小助理，請選擇新題目。\", \"fa-rotate-left\");\n    }\n\n    /* Navigation between steps */\n    function goToStep(stepNumber) {\n      if (stepNumber > 0 && !appState.topic) {\n        showToast(\"請先輸入作文題目。\", \"fa-exclamation\");\n        stepNumber = 0;\n      }\n\n      appState.currentStep = stepNumber;\n\n      // Toggle views\n      document.getElementById('viewSetup').classList.toggle('hidden', stepNumber !== 0);\n      document.getElementById('step1View').classList.toggle('hidden', stepNumber !== 1);\n      document.getElementById('step2View').classList.toggle('hidden', stepNumber !== 2);\n      document.getElementById('step3View').classList.toggle('hidden', stepNumber !== 3);\n      document.getElementById('step4View').classList.toggle('hidden', stepNumber !== 4);\n      document.getElementById('step5View').classList.toggle('hidden', stepNumber !== 5);\n\n      // Meta badges in header\n      const metaBadges = document.getElementById('activeMetaBadges');\n      if (stepNumber > 0) {\n        metaBadges.classList.remove('hidden');\n        document.getElementById('badgeGradeText').textContent = appState.grade;\n        document.getElementById('badgeGenreText').textContent = appState.genre;\n      } else {\n        metaBadges.classList.add('hidden');\n      }\n\n      updateNavTabs();\n\n      // Trigger automatic generation if step data is missing\n      if (stepNumber === 1 && !appState.step1Data) {\n        generateStep1Analysis();\n      } else if (stepNumber === 2 && appState.chatHistory.length === 0) {\n        startSocraticChat();\n      } else if (stepNumber === 3 && !appState.step3Data) {\n        generateVocabularySupport();\n      } else if (stepNumber === 4 && !appState.step4Data) {\n        generateStep4Outline();\n      } else if (stepNumber === 5) {\n        document.querySelectorAll('.currentTopicInline').forEach(el => el.textContent = appState.topic);\n      }\n    }\n\n    function switchStepTab(targetStep) {\n      if (!appState.topic) {\n        showToast(\"請先在第一頁設定題目。\", \"fa-pen\");\n        return;\n      }\n      goToStep(targetStep);\n    }\n\n    function updateNavTabs() {\n      for (let i = 1; i <= 5; i++) {\n        const tab = document.getElementById(`stepTab-${i}`);\n        const num = tab.querySelector('.step-num');\n        if (i === appState.currentStep) {\n          tab.className = \"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-black transition bg-amber-400 text-white shadow-sm\";\n          num.className = \"w-6 h-6 rounded-full bg-white text-amber-700 flex items-center justify-center text-xs font-black step-num\";\n        } else if (i < appState.currentStep) {\n          tab.className = \"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-bold transition text-emerald-800 hover:bg-amber-200\";\n          num.className = \"w-6 h-6 rounded-full bg-emerald-500 text-white flex items-center justify-center text-xs font-black step-num\";\n        } else {\n          tab.className = \"step-tab flex items-center gap-2 px-3 py-1 rounded-full text-xs sm:text-sm font-medium transition text-slate-500 hover:bg-amber-200/50\";\n          num.className = \"w-6 h-6 rounded-full bg-slate-200 text-slate-600 flex items-center justify-center text-xs font-bold step-num\";\n        }\n      }\n    }\n\n    /* Step 0 -> Step 1 Start */\n    function startWritingCoach() {\n      const topic = document.getElementById('topicInput').value.trim();\n      if (!topic) {\n        showToast(\"請輸入作文題目。\", \"fa-pencil\");\n        document.getElementById('topicInput').focus();\n        return;\n      }\n\n      // Collect grade\n      const gradeSelected = document.querySelector('input[name=\"studentGrade\"]:checked').value;\n      // Collect genre\n      const genreSelected = document.querySelector('input[name=\"writingGenre\"]:checked').value;\n\n      appState.topic = topic;\n      appState.grade = gradeSelected;\n      appState.genre = genreSelected;\n\n      // Update topic displays\n      document.getElementById('displayTopic1').textContent = topic;\n      document.getElementById('displayTopic3').textContent = topic;\n      document.getElementById('displayTopic4').textContent = topic;\n\n      goToStep(1);\n    }\n\n    /* Gemini API Request Helper with Exponential Backoff */\n    async function callGemini(payload, retries = 3, delay = 1000) {\n      const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3-flash-preview:generateContent?key=${appState.apiKey}`;\n      \n      for (let attempt = 0; attempt < retries; attempt++) {\n        try {\n          const res = await fetch(apiUrl, {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(payload)\n          });\n          \n          if (!res.ok) {\n            throw new Error(`HTTP ${res.status}: ${res.statusText}`);\n          }\n          const data = await res.json();\n          return data;\n        } catch (err) {\n          if (attempt === retries - 1) throw err;\n          await new Promise(r => setTimeout(r, delay * Math.pow(2, attempt)));\n        }\n      }\n    }\n\n    /* STEP 1: Generate Topic Analysis */\n    async function generateStep1Analysis() {\n      const loadingEl = document.getElementById('step1Loading');\n      const contentEl = document.getElementById('step1Content');\n      loadingEl.classList.remove('hidden');\n      contentEl.classList.add('hidden');\n\n      const prompt = `學生年級：香港小學【${appState.grade}】\n文體：【${appState.genre}】\n作文題目：【${appState.topic}】\n\n請根據香港小學中文科寫作要求，為學生進行第一步「審題解析」。\n輸出必須為嚴格的 JSON 格式：\n{\n  \"keywords\": [\"關鍵字1及其作用簡釋\", \"關鍵字2及其作用簡釋\", \"關鍵字3及其作用簡釋\"],\n  \"focus\": \"寫作核心重點（向小學生說明本文最關鍵要寫出甚麼，80字以內）\",\n  \"genrePoints\": [\"文體特色要點1（如：記敘文必須有六要素）\", \"文體特色要點2\", \"文體特色要點3\"],\n  \"coachAdvice\": \"親切的提示（50字以內）\"\n}`;\n\n      const payload = {\n        contents: [{ parts: [{ text: prompt }] }],\n        generationConfig: {\n          responseMimeType: \"application/json\"\n        },\n        systemInstruction: {\n          parts: [{ text: SYSTEM_INSTRUCTION_BASE }]\n        }\n      };\n\n      try {\n        const result = await callGemini(payload);\n        const jsonText = result.candidates?.[0]?.content?.parts?.[0]?.text;\n        if (!jsonText) throw new Error(\"無效的回傳內容\");\n        \n        const data = JSON.parse(jsonText);\n        appState.step1Data = data;\n        renderStep1(data);\n      } catch (err) {\n        // Fallback friendly static data if offline or API throttled\n        const fallback = {\n          keywords: [`「${appState.topic.slice(0, 4)}」：決定文章的主題與情境`, \"「自己或經歷」：寫出屬於你的真實體會\", \"「過程與收穫」：交代事情起伏與心靈成長\"],\n          focus: `重點在於圍繞「${appState.topic}」，清楚交代時間、地點、人物，並詳細刻畫最難忘、最有意義的具體情節。`,\n          genrePoints: [`符合${appState.genre}的結構要點`, \"抓住感官細節（看到、聽到、感受到的事物）\", \"加入真摯的情感抒發，點明中心主題\"],\n          coachAdvice: `審題是寫作的第一步。先想清楚題目的核心，下筆時便不會偏離方向。`\n        };\n        appState.step1Data = fallback;\n        renderStep1(fallback);\n      } finally {\n        loadingEl.classList.add('hidden');\n        contentEl.classList.remove('hidden');\n      }\n    }\n\n    function renderStep1(data) {\n      const keywordsList = document.getElementById('keywordsList');\n      keywordsList.innerHTML = data.keywords.map(kw => `\n        <li class=\"flex items-start gap-1.5 text-slate-700\">\n          <i class=\"fa-solid fa-circle-check text-amber-500 mt-1 text-xs\"></i>\n          <span>${kw}</span>\n        </li>\n      `).join('');\n\n      document.getElementById('focusSummary').textContent = data.focus;\n\n      const genrePointsList = document.getElementById('genrePointsList');\n      genrePointsList.innerHTML = data.genrePoints.map(pt => `\n        <li class=\"flex items-start gap-1.5 text-slate-700\">\n          <i class=\"fa-solid fa-star text-emerald-500 mt-1 text-xs\"></i>\n          <span>${pt}</span>\n        </li>\n      `).join('');\n\n      document.getElementById('coachAdviceStep1').textContent = \n        data.coachAdvice + \" 你已經想到很好的內容，請再逐步完成作文。\";\n    }\n\n    /* STEP 2: Socratic Guidance (Ask ONE question at a time) */\n    async function startSocraticChat() {\n      appState.questionCount = 1;\n      updateChatCounter();\n\n      const initialQuestion = `你好。我們開始構思《${appState.topic}》。\\n\\n請問這件事發生在甚麼時候和甚麼地方？當時還有誰和你在一起？`;\n      \n      appendChatMessage(\"ai\", initialQuestion);\n\n      // Record in Gemini turn history\n      appState.geminiHistory = [\n        {\n          role: \"user\",\n          parts: [{ text: `學生年級：${appState.grade}，文體：${appState.genre}，題目：《${appState.topic}》。請作為陳老師開始引導構思。` }]\n        },\n        {\n          role: \"model\",\n          parts: [{ text: initialQuestion + \"\\n\\n你已經想到很好的內容，請再逐步完成作文。\" }]\n        }\n      ];\n    }\n\n    function updateChatCounter() {\n      const counterEl = document.getElementById('chatQuestionCounter');\n      counterEl.textContent = `第 ${appState.questionCount} 個引導問題`;\n      if (appState.questionCount >= 3) {\n        document.getElementById('step2FinishContainer').classList.remove('hidden');\n      }\n    }\n\n    function appendChatMessage(role, text) {\n      const container = document.getElementById('chatScrollArea');\n      const bubble = document.createElement('div');\n      \n      if (role === 'ai') {\n        bubble.className = \"flex items-start gap-3\";\n        bubble.innerHTML = `\n          <div class=\"w-9 h-9 rounded-2xl bg-amber-400 text-white flex-shrink-0 flex items-center justify-center text-sm shadow-sm\">\n            <span>👨‍🏫</span>\n          </div>\n          <div class=\"chat-bubble-ai bg-white border border-amber-200 rounded-2xl rounded-tl-sm p-4 text-xs sm:text-sm text-slate-800 shadow-sm max-w-[85%] whitespace-pre-line leading-relaxed\">\n            ${escapeHtml(text)}\n          </div>\n        `;\n      } else {\n        bubble.className = \"flex items-start justify-end gap-2\";\n        bubble.innerHTML = `\n          <div class=\"bg-gradient-to-r from-amber-500 to-orange-500 text-white rounded-2xl rounded-tr-sm p-3.5 text-xs sm:text-sm shadow max-w-[85%] whitespace-pre-line leading-relaxed font-medium\">\n            ${escapeHtml(text)}\n          </div>\n          <div class=\"w-8 h-8 rounded-full bg-slate-200 text-slate-600 flex-shrink-0 flex items-center justify-center text-xs font-bold\">\n            <i class=\"fa-solid fa-user\"></i>\n          </div>\n        `;\n      }\n\n      container.appendChild(bubble);\n      container.scrollTop = container.scrollHeight;\n    }\n\n    function appendQuickChat(text) {\n      const input = document.getElementById('chatStudentInput');\n      input.value = text;\n      input.focus();\n    }\n\n    async function handleStudentAnswer(e) {\n      e.preventDefault();\n      const input = document.getElementById('chatStudentInput');\n      const answer = input.value.trim();\n      if (!answer) return;\n\n      input.value = \"\";\n      appendChatMessage(\"student\", answer);\n\n      // Disable send button and show typing\n      const btnSend = document.getElementById('btnSendAnswer');\n      const typing = document.getElementById('chatTypingIndicator');\n      btnSend.disabled = true;\n      typing.classList.remove('hidden');\n\n      // Add to conversation\n      appState.geminiHistory.push({\n        role: \"user\",\n        parts: [{ text: answer }]\n      });\n\n      const instruction = `${SYSTEM_INSTRUCTION_BASE}\n當前是【第二步：引導構思】。\n學生回答了你的上一個問題。\n你必須遵從的嚴格規則：\n1. 先簡短讚賞、肯定學生的回應，指出他答得好或有趣的細節（1-2句）。\n2. 然後【只提出一條全新的啟發問題】，引導下一步的思考。\n   例如：思考事件起因、人物動作、感官細節、最緊張刺激的高潮、或是內心的轉變與感受。\n3. 絕對【不要代學生寫作】，不要提供大段示範文字。\n4. 每次回應最後一行必須獨立成段加上：「你已經想到很好的內容，請再逐步完成作文。」`;\n\n      const payload = {\n        contents: appState.geminiHistory,\n        systemInstruction: {\n          parts: [{ text: instruction }]\n        }\n      };\n\n      try {\n        const result = await callGemini(payload);\n        const reply = result.candidates?.[0]?.content?.parts?.[0]?.text || \"這個想法很好。接下來發生了甚麼意想不到的事？\\n\\n你已經想到很好的內容，請再逐步完成作文。\";\n        \n        appState.geminiHistory.push({\n          role: \"model\",\n          parts: [{ text: reply }]\n        });\n\n        appendChatMessage(\"ai\", reply);\n        appState.questionCount++;\n        updateChatCounter();\n\n      } catch (err) {\n        // Fallback questions for primary school narrative/descriptive sequence\n        const fallbackQuestions = [\n          \"這個回答很生動。在那個過程中，有沒有特別的小插曲，或最難忘的情景？\\n\\n你已經想到很好的內容，請再逐步完成作文。\",\n          \"這個描述很清晰。當時周圍的人有甚麼反應？你看見或聽見了甚麼？\\n\\n你已經想到很好的內容，請再逐步完成作文。\",\n          \"這個想法很有意思。事情結束後，你的心情是怎樣的？你學到了甚麼？\\n\\n你已經想到很好的內容，請再逐步完成作文。\"\n        ];\n        const nextFallback = fallbackQuestions[(appState.questionCount - 1) % fallbackQuestions.length];\n        appendChatMessage(\"ai\", nextFallback);\n        appState.questionCount++;\n        updateChatCounter();\n      } finally {\n        btnSend.disabled = false;\n        typing.classList.add('hidden');\n      }\n    }\n\n    /* STEP 3: Vocabulary and Sentence Support */\n    async function generateVocabularySupport(forceRegen = false) {\n      if (appState.step3Data && !forceRegen) {\n        renderStep3(appState.step3Data);\n        return;\n      }\n\n      const loadingEl = document.getElementById('step3Loading');\n      const contentEl = document.getElementById('step3Content');\n      loadingEl.classList.remove('hidden');\n      contentEl.classList.add('hidden');\n\n      // Synthesize conversation context\n      const studentIdeas = appState.geminiHistory\n        .filter(t => t.role === 'user')\n        .map(t => t.parts[0].text)\n        .join(\" \");\n\n      const prompt = `學生年級：香港小學【${appState.grade}】\n文體：【${appState.genre}】\n題目：【${appState.topic}】\n學生目前的構思細節：${studentIdeas || \"無額外細節，請依年級與題目量身訂造\"}\n\n請為這位小學生提供精準的【第三步：詞彙支援】。\n輸出必須為嚴格的 JSON 格式：\n{\n  \"adjectives\": [\"形容詞1\", \"形容詞2\", \"形容詞3\", \"形容詞4\", \"形容詞5\"],\n  \"feelings\": [\"感受詞1\", \"感受詞2\", \"感受詞3\", \"感受詞4\", \"感受詞5\"],\n  \"idioms\": [\n    { \"word\": \"成語1\", \"meaning\": \"簡潔解釋\", \"example\": \"簡短例句\" },\n    { \"word\": \"成語2\", \"meaning\": \"簡潔解釋\", \"example\": \"簡短例句\" },\n    { \"word\": \"成語3\", \"meaning\": \"簡潔解釋\", \"example\": \"簡短例句\" }\n  ],\n  \"sentencePatterns\": [\n    { \"type\": \"感官描寫\", \"pattern\": \"你看見/聽見/聞到的景物描寫示範句式\" },\n    { \"type\": \"心理描寫\", \"pattern\": \"內心活動與情緒起伏示範句式\" },\n    { \"type\": \"動作描寫\", \"pattern\": \"生動連續動詞的動作描寫示範句式\" }\n  ]\n}`;\n\n      const payload = {\n        contents: [{ parts: [{ text: prompt }] }],\n        generationConfig: {\n          responseMimeType: \"application/json\"\n        },\n        systemInstruction: {\n          parts: [{ text: SYSTEM_INSTRUCTION_BASE }]\n        }\n      };\n\n      try {\n        const result = await callGemini(payload);\n        const jsonText = result.candidates?.[0]?.content?.parts?.[0]?.text;\n        const data = JSON.parse(jsonText);\n        appState.step3Data = data;\n        renderStep3(data);\n      } catch (err) {\n        // Fallback default dictionary for HK primary students\n        const fallback = {\n          adjectives: [\"五彩繽紛\", \"熱鬧非凡\", \"小心翼翼\", \"風和日麗\", \"井井有條\"],\n          feelings: [\"欣喜若狂\", \"忐忑不安\", \"如釋重負\", \"依依不捨\", \"心滿意足\"],\n          idioms: [\n            { word: \"津津有味\", meaning: \"形容很有滋味或很有興趣。\", example: \"大家都吃得津津有味。\" },\n            { word: \"齊心協力\", meaning: \"眾人同心合力。\", example: \"只要我們齊心協力，困難便能解決。\" },\n            { word: \"興致勃勃\", meaning: \"形容興趣很濃厚。\", example: \"同學們興致勃勃地討論著活動。\" }\n          ],\n          sentencePatterns: [\n            { type: \"感官描寫\", pattern: \"微風輕輕吹過，空氣中飄來陣陣花草的清香，令人心曠神怡。\" },\n            { type: \"心理描寫\", pattern: \"我的心中像十五個吊桶打水，七上八下，雙手更不由自主地微微顫抖。\" },\n            { type: \"動作描寫\", pattern: \"他三步並作兩步衝上前，一把拉住我的衣角，氣喘吁吁地說道。\" }\n          ]\n        };\n        appState.step3Data = fallback;\n        renderStep3(fallback);\n      } finally {\n        loadingEl.classList.add('hidden');\n        contentEl.classList.remove('hidden');\n      }\n    }\n\n    function renderStep3(data) {\n      // 1. Adjectives\n      const adjContainer = document.getElementById('adjContainer');\n      adjContainer.innerHTML = data.adjectives.map(word => `\n        <button type=\"button\" onclick=\"collectWord('${escapeHtml(word)}')\" class=\"word-card p-2.5 rounded-xl border border-orange-200 bg-orange-50 hover:bg-orange-100 text-orange-900 font-bold text-xs sm:text-sm text-center transition flex items-center justify-center gap-1 group shadow-xs\">\n          <span>${word}</span>\n          <i class=\"fa-solid fa-plus text-[10px] text-orange-400 group-hover:scale-125 transition\"></i>\n        </button>\n      `).join('');\n\n      // 2. Feelings\n      const feelingsContainer = document.getElementById('feelingsContainer');\n      feelingsContainer.innerHTML = data.feelings.map(word => `\n        <button type=\"button\" onclick=\"collectWord('${escapeHtml(word)}')\" class=\"word-card p-2.5 rounded-xl border border-rose-200 bg-rose-50 hover:bg-rose-100 text-rose-900 font-bold text-xs sm:text-sm text-center transition flex items-center justify-center gap-1 group shadow-xs\">\n          <span>${word}</span>\n          <i class=\"fa-solid fa-plus text-[10px] text-rose-400 group-hover:scale-125 transition\"></i>\n        </button>\n      `).join('');\n\n      // 3. Idioms\n      const idiomsContainer = document.getElementById('idiomsContainer');\n      idiomsContainer.innerHTML = data.idioms.map(item => `\n        <div class=\"p-3.5 rounded-2xl border border-purple-200 bg-purple-50/60 flex flex-col justify-between\">\n          <div>\n            <div class=\"flex items-center justify-between mb-1\">\n              <span class=\"font-black text-purple-900 text-base\">${item.word}</span>\n              <button onclick=\"collectWord('${escapeHtml(item.word)}')\" class=\"px-2 py-0.5 bg-purple-200 hover:bg-purple-300 text-purple-800 text-[11px] font-bold rounded-lg transition\">\n                + 收藏\n              </button>\n            </div>\n            <p class=\"text-xs text-purple-900/80 mb-2\">${item.meaning}</p>\n          </div>\n          <div class=\"text-[11px] bg-white/80 p-2 rounded-lg text-slate-600 border border-purple-100\">\n            <span class=\"text-purple-600 font-bold\">例：</span>${item.example}\n          </div>\n        </div>\n      `).join('');\n\n      // 4. Sentences\n      const sentencesContainer = document.getElementById('sentencesContainer');\n      sentencesContainer.innerHTML = data.sentencePatterns.map(item => `\n        <div class=\"p-3.5 rounded-2xl border border-sky-200 bg-sky-50/50 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2\">\n          <div class=\"flex-1\">\n            <span class=\"inline-block px-2 py-0.5 bg-sky-200 text-sky-800 rounded-md text-[11px] font-bold mb-1\">${item.type}</span>\n            <p class=\"text-xs sm:text-sm text-slate-800 font-medium\">「${item.pattern}」</p>\n          </div>\n          <button onclick=\"collectSentence('${escapeHtml(item.pattern)}')\" class=\"px-3 py-1 bg-white hover:bg-sky-100 text-sky-700 border border-sky-300 rounded-xl text-xs font-bold transition flex items-center gap-1 self-end sm:self-auto\">\n            <i class=\"fa-regular fa-bookmark\"></i> 收藏句子\n          </button>\n        </div>\n      `).join('');\n    }\n\n    /* Word Bank Notebook Management */\n    function collectWord(word) {\n      if (appState.collectedWords.has(word)) {\n        showToast(`「${word}」已在錦囊中。`, 'fa-circle-check');\n        return;\n      }\n      appState.collectedWords.add(word);\n      updateWordBankCount();\n      renderWordBank();\n      showToast(`已收藏好詞：「${word}」`, 'fa-box-archive');\n    }\n\n    function collectSentence(sentence) {\n      if (appState.collectedSentences.includes(sentence)) {\n        showToast(\"此句已收藏。\", 'fa-circle-check');\n        return;\n      }\n      appState.collectedSentences.push(sentence);\n      updateWordBankCount();\n      renderWordBank();\n      showToast(\"已收藏描寫句式。\", 'fa-bookmark');\n    }\n\n    function updateWordBankCount() {\n      const count = appState.collectedWords.size + appState.collectedSentences.length;\n      document.getElementById('collectedWordsCount').textContent = count;\n    }\n\n    function renderWordBank() {\n      const tagsContainer = document.getElementById('wordBankTags');\n      if (appState.collectedWords.size === 0) {\n        tagsContainer.innerHTML = `<p class=\"text-xs text-slate-400 py-3 text-center w-full\">尚未收藏詞語。在第三步按一下詞卡，即可加入錦囊。</p>`;\n      } else {\n        tagsContainer.innerHTML = Array.from(appState.collectedWords).map(w => `\n          <span class=\"inline-flex items-center gap-1 px-2.5 py-1 bg-amber-100 text-amber-900 rounded-xl text-xs font-bold border border-amber-300\">\n            <span>${w}</span>\n            <button onclick=\"removeWord('${escapeHtml(w)}')\" class=\"text-amber-500 hover:text-amber-800 ml-1\"><i class=\"fa-solid fa-xmark text-[10px]\"></i></button>\n          </span>\n        `).join('');\n      }\n\n      const cardsContainer = document.getElementById('wordBankCards');\n      if (appState.collectedSentences.length === 0) {\n        cardsContainer.innerHTML = `<p class=\"text-xs text-slate-400 py-2 text-center w-full\">暫無收藏長句。</p>`;\n      } else {\n        cardsContainer.innerHTML = appState.collectedSentences.map((s, idx) => `\n          <div class=\"p-2.5 rounded-xl border border-sky-200 bg-sky-50 text-xs text-slate-700 flex items-start justify-between gap-2\">\n            <span>${s}</span>\n            <button onclick=\"removeSentence(${idx})\" class=\"text-slate-400 hover:text-rose-500\"><i class=\"fa-solid fa-trash-can text-xs\"></i></button>\n          </div>\n        `).join('');\n      }\n    }\n\n    function removeWord(word) {\n      appState.collectedWords.delete(word);\n      updateWordBankCount();\n      renderWordBank();\n    }\n    function removeSentence(index) {\n      appState.collectedSentences.splice(index, 1);\n      updateWordBankCount();\n      renderWordBank();\n    }\n    function clearWordBank() {\n      appState.collectedWords.clear();\n      appState.collectedSentences = [];\n      updateWordBankCount();\n      renderWordBank();\n      showToast(\"已清空錦囊。\", \"fa-trash\");\n    }\n\n    function toggleNotebook() {\n      const drawer = document.getElementById('wordBankDrawer');\n      const backdrop = document.getElementById('drawerBackdrop');\n      const isClosed = drawer.classList.contains('translate-x-full');\n\n      if (isClosed) {\n        renderWordBank();\n        drawer.classList.remove('translate-x-full');\n        backdrop.classList.remove('hidden');\n        setTimeout(() => backdrop.classList.remove('opacity-0'), 10);\n      } else {\n        drawer.classList.add('translate-x-full');\n        backdrop.classList.add('opacity-0');\n        setTimeout(() => backdrop.classList.add('hidden'), 300);\n      }\n    }\n\n    function copyWordBankToClipboard() {\n      const words = Array.from(appState.collectedWords).join(\"、\");\n      const sentences = appState.collectedSentences.map((s, i) => `${i + 1}. ${s}`).join(\"\\n\");\n      const text = `【我的寫作錦囊】\\n題目：《${appState.topic}》\\n精選詞語：${words || '無'}\\n\\n優美句式：\\n${sentences || '無'}`;\n      copyToClipboardText(text);\n      showToast(\"已複製全部錦囊文字。\", \"fa-check\");\n    }\n\n    /* STEP 4: Outline Structuring (Only outlines, no ghostwriting!) */\n    async function generateStep4Outline() {\n      const loadingEl = document.getElementById('step4Loading');\n      const contentEl = document.getElementById('step4Content');\n      loadingEl.classList.remove('hidden');\n      contentEl.classList.add('hidden');\n\n      const studentIdeas = appState.geminiHistory\n        .filter(t => t.role === 'user')\n        .map(t => t.parts[0].text)\n        .join(\"；\");\n\n      const prompt = `學生年級：香港小學【${appState.grade}】\n文體：【${appState.genre}】\n作文題目：【${appState.topic}】\n學生在引導過程中的想法筆記：${studentIdeas || \"無特別回答，請依據小學題目提供清晰框架引導\"}\n\n請為學生整理【第四步：作文大綱】。\n核心禁令：\n- 只提供大綱框架與提示思考方向，【絕不要代學生寫出完整內容或範文】！\n- 必須分開四個部分：開頭、經過、高潮、結尾。\n\n輸出格式為嚴格 JSON：\n{\n  \"intro\": \"【開頭提示】：明確交代時間、地點、人物背景的寫作引導要點（60字以內）\",\n  \"development\": \"【經過提示】：事情如何一步步展開、順序與轉折的提示要點（80字以內）\",\n  \"climax\": \"【高潮提示】：最關鍵、最深刻一幕的描寫提示，引導學生寫出細節與動作（80字以內）\",\n  \"ending\": \"【結尾提示】：如何抒發感想、總結體會、點明主題的提示要點（60字以內）\"\n}`;\n\n      const payload = {\n        contents: [{ parts: [{ text: prompt }] }],\n        generationConfig: {\n          responseMimeType: \"application/json\"\n        },\n        systemInstruction: {\n          parts: [{ text: SYSTEM_INSTRUCTION_BASE }]\n        }\n      };\n\n      try {\n        const result = await callGemini(payload);\n        const jsonText = result.candidates?.[0]?.content?.parts?.[0]?.text;\n        const data = JSON.parse(jsonText);\n        appState.step4Data = data;\n        renderStep4(data);\n      } catch (err) {\n        const fallback = {\n          intro: `點明時間、環境氛圍以及有誰同行，運用一兩句環境描寫營造氣氛。`,\n          development: `按照事情發展的先後次序，交代出發、到達或事情開始時的所見所聞。`,\n          climax: `詳細聚焦最關鍵的一幕（如突發困難、最精彩的比賽、最感動的對話），多用動作、神態和心理描寫。`,\n          ending: `總結這次經歷帶給你的啟發或難忘感受，做到首尾呼應。`\n        };\n        appState.step4Data = fallback;\n        renderStep4(fallback);\n      } finally {\n        loadingEl.classList.add('hidden');\n        contentEl.classList.remove('hidden');\n      }\n    }\n\n    function renderStep4(data) {\n      document.getElementById('outlineIntro').textContent = data.intro;\n      document.getElementById('outlineDevelopment').textContent = data.development;\n      document.getElementById('outlineClimax').textContent = data.climax;\n      document.getElementById('outlineEnding').textContent = data.ending;\n    }\n\n    function getFullOutlineText() {\n      const introNote = document.getElementById('noteIntro').value;\n      const devNote = document.getElementById('noteDev').value;\n      const climaxNote = document.getElementById('noteClimax').value;\n      const endingNote = document.getElementById('noteEnding').value;\n\n      return `《${appState.topic}》寫作大綱（${appState.grade}・${appState.genre}）\\n` +\n        `-----------------------------------------\\n` +\n        `【開頭】時間、地點、人物：\\n` +\n        `・指導方向：${document.getElementById('outlineIntro').textContent}\\n` +\n        (introNote ? `・我的構思：${introNote}\\n` : '') +\n        `\\n【經過】事情發展：\\n` +\n        `・指導方向：${document.getElementById('outlineDevelopment').textContent}\\n` +\n        (devNote ? `・我的構思：${devNote}\\n` : '') +\n        `\\n【高潮】最重要事件：\\n` +\n        `・指導方向：${document.getElementById('outlineClimax').textContent}\\n` +\n        (climaxNote ? `・我的構思：${climaxNote}\\n` : '') +\n        `\\n【結尾】感受及反思：\\n` +\n        `・指導方向：${document.getElementById('outlineEnding').textContent}\\n` +\n        (endingNote ? `・我的構思：${endingNote}\\n` : '') +\n        `-----------------------------------------\\n` +\n        `提示：大綱是文章的框架。動筆時請加入具體細節與感受。`;\n    }\n\n    function copyOutline() {\n      const fullText = getFullOutlineText();\n      copyToClipboardText(fullText);\n      showToast(\"已複製完整大綱與筆記。\", \"fa-check\");\n    }\n\n    function printOutline() {\n      const printWindow = window.open('', '_blank');\n      const fullText = getFullOutlineText().replace(/\\n/g, '<br>');\n      printWindow.document.write(`\n        <html>\n          <head>\n            <title>作文大綱 - ${appState.topic}</title>\n            <style>\n              body { font-family: \"Noto Sans TC\", sans-serif; padding: 40px; line-height: 1.8; color: #333; }\n              h1 { color: #d97706; border-bottom: 2px solid #f59e0b; padding-bottom: 10px; }\n              .box { background: #fffbeb; border: 1px solid #fde68a; padding: 20px; border-radius: 12px; }\n            </style>\n          </head>\n          <body>\n            <h1>AI中文寫作小助理 - 學生大綱檔案</h1>\n            <div class=\"box\">${fullText}</div>\n            <script>window.onload = function() { window.print(); }<\\/script>\n          </body>\n        </html>\n      `);\n      printWindow.document.close();\n    }\n\n    /* STEP 5: Self Check Logic */\n    function updateChecklistProgress() {\n      const checkboxes = document.querySelectorAll('.check-item');\n      let checked = 0;\n      checkboxes.forEach(cb => {\n        if (cb.checked) checked++;\n      });\n      appState.checkedItems = checked;\n      document.getElementById('checkedCount').textContent = checked;\n\n      const rewardBox = document.getElementById('completionRewardBox');\n      if (checked >= 5) {\n        rewardBox.classList.remove('hidden');\n        celebrateWithConfetti();\n      } else {\n        rewardBox.classList.add('hidden');\n      }\n    }\n\n    function celebrateWithConfetti() {\n      if (typeof confetti === 'function') {\n        confetti({\n          particleCount: 80,\n          spread: 70,\n          origin: { y: 0.6 }\n        });\n      }\n    }\n\n    /* Optional Formative Draft Feedback from Teacher (No Ghostwriting) */\n    async function requestDraftFeedback() {\n      const draft = document.getElementById('studentDraftInput').value.trim();\n      if (!draft) {\n        showToast(\"請先在文字框內輸入或貼上一段初稿。\", \"fa-pen-to-square\");\n        document.getElementById('studentDraftInput').focus();\n        return;\n      }\n\n      const btn = document.getElementById('btnDraftCheck');\n      const resultBox = document.getElementById('draftFeedbackResult');\n      const textContainer = document.getElementById('draftFeedbackText');\n\n      btn.disabled = true;\n      btn.innerHTML = `<i class=\"fa-solid fa-spinner animate-spin\"></i> <span>陳老師正在細閱並準備評語...</span>`;\n\n      const prompt = `學生年級：香港小學【${appState.grade}】\n作文題目：【${appState.topic}】\n文體：【${appState.genre}】\n學生寫的初稿段落：\n\"${draft}\"\n\n你是一位溫柔熱情的香港小學資深中文老師。請給予具體、鼓勵式的回饋：\n要求：\n1. 找出學生寫得最好的2個亮點（例如用詞好、細節生動或情感真摯）。\n2. 給予1至2個具啟發性的微調建議（例如「如果能加一句聽到的聲音會更棒」）。\n3. 嚴禁直接幫學生重寫整段文章！\n4. 每次回應最後一行必須獨立成段加上：「你已經想到很好的內容，請再逐步完成作文。」`;\n\n      const payload = {\n        contents: [{ parts: [{ text: prompt }] }],\n        systemInstruction: {\n          parts: [{ text: SYSTEM_INSTRUCTION_BASE }]\n        }\n      };\n\n      try {\n        const result = await callGemini(payload);\n        const feedback = result.candidates?.[0]?.content?.parts?.[0]?.text;\n        textContainer.innerHTML = feedback.replace(/\\n/g, '<br>');\n        resultBox.classList.remove('hidden');\n        showToast(\"陳老師已完成批閱，請查看評語。\", \"fa-graduation-cap\");\n      } catch (err) {\n        textContainer.innerHTML = `\n          <strong>🌟 亮點肯定：</strong> 你的文筆很自然流暢，而且內容十分切合題目《${appState.topic}》！<br><br>\n          <strong>老師建議：</strong> 請在重點段落加入一兩個四字成語，或描寫當時的心跳感覺，使文章更加生動。<br><br>\n          <strong>你已經想到很好的內容，請再逐步完成作文。</strong>\n        `;\n        resultBox.classList.remove('hidden');\n      } finally {\n        btn.disabled = false;\n        btn.innerHTML = `<i class=\"fa-solid fa-chalkboard-user\"></i> <span>請陳老師給予指導評語</span>`;\n      }\n    }\n\n    /* Clipboard Copy Fallback Safe Helper */\n    function copyToClipboardText(text) {\n      const tempTextArea = document.createElement(\"textarea\");\n      tempTextArea.value = text;\n      tempTextArea.style.position = \"fixed\";\n      tempTextArea.style.left = \"-999999px\";\n      tempTextArea.style.top = \"-999999px\";\n      document.body.appendChild(tempTextArea);\n      tempTextArea.focus();\n      tempTextArea.select();\n      try {\n        document.execCommand('copy');\n      } catch (err) {\n        console.error(\"Copy failed\", err);\n      }\n      document.body.removeChild(tempTextArea);\n    }\n\n    /* HTML Escape Helper */\n    function escapeHtml(string) {\n      if (!string) return '';\n      return String(string)\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#39;');\n    }\n  </script>\n</body>\n</html>\n";
